mod solution;

fn main() {
    let cases = [
    (r#"[10,9,2,5,3,7,101,18]"#, r#"4"#),
    (r#"[3,2,1]"#, r#"1"#),
    (r#"
[3,2,1]
"#, r#"1"#),
    (r#"  
[10,9,2,5,3,7,101,18]
  "#, r#"4"#),
    ];
    for (case_index, (input, expected)) in cases.iter().enumerate() {
        if solution::solve(input) != *expected {
            eprintln!("PRIVATE CASE {} FAILED", case_index + 1);
            std::process::exit(1);
        }
    }
    println!("PASS lis-patience");
}
